brand_css_dark:
:root {
--radius-none: 0;
--radius-sm: 4px;      /* 직진배송·무료배송 배지, 상품 사진 */
--radius-md: 8px;      /* 버튼·입력·키워드 배너 */
--radius-lg: 12px;     /* 쿠폰 카드·메인 배너 */
--radius-xl: 16px;     /* 바텀시트 상단 */
--radius-full: 9999px; /* 필터 칩·카카오 로그인 버튼·스위치 */
--shadow-none: none;                              /* 상품 카드·탭·배너 — 기본 */
--shadow-sm: 0px 2px 8px rgba(0, 0, 0, 0.1);      /* shadow-small — 플로팅 버튼·툴팁 */
--shadow-md: 0px 4px 16px rgba(0, 0, 0, 0.1);     /* shadow-medium — 드롭다운·토스트 */
--shadow-lg: 0px 8px 32px rgba(0, 0, 0, 0.1);     /* shadow-large — 바텀시트·모달 */
--shadow-xl: 0px 0px 16px rgba(0, 0, 0, 0.3);     /* shadow-selected — 사진 위 선택 강조 */
--duration-fast: 150ms;   /* 찜 하트 채움·버튼 눌림 */
--duration-base: 250ms;   /* 탭 전환·칩 선택 */
--duration-slow: 350ms;   /* 바텀시트 올라옴 */
--ease-out: cubic-bezier(0.2, 0, 0, 1);
--ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
}
:root {
  /* Primary - Zigzag Pink: 다크에서도 brand-zigzag-primary = pink-400 그대로 */
  --color-primary-50:  #32202F;  /* pink-400 12% on gray-950 — brand-zigzag-background(다크) */
  --color-primary-100: #4F1D45;  /* pink-900 */
  --color-primary-200: #69275B;  /* pink-800 — brand-zigzag-border(다크) */
  --color-primary-300: #8F357C;  /* pink-700 */
  --color-primary-400: #B5449E;  /* pink-600 */
  --color-primary-500: #F55DD6;  /* pink-400 — 찜·바로가기·스위치 ON */
  --color-primary-600: #E356C6;  /* pink-450 — hover */
  --color-primary-700: #D14FB7;  /* pink-550 — pressed */
  --color-primary-800: #F88DE2;  /* pink-300 — 어두운 면 위 링크 */
  --color-primary-900: #FAAEEA;  /* pink-200 */

  /* Secondary - 역할 색 (다크 값) */
  --color-secondary-500: #5E45D9;  /* purple-550 — service-z-delivery(다크) */
  --color-accent-500:    #FB4333;  /* coral-red-400 — accent-primary(다크 동일) */
  --color-ai-500:        #644BE8;  /* purple-500 */
  --color-kakao:         #FEE500;

  /* Neutral - ZDS gray (다크에서는 위계 반전) */
  --color-neutral-0:    #050505;  /* gray-990 — background-base */
  --color-neutral-50:   #121212;  /* gray-970 */
  --color-neutral-100:  #181818;  /* gray-950 — surface */
  --color-neutral-200:  #1F2020;  /* gray-900 — elevated */
  --color-neutral-300:  #292B2B;  /* gray-800 — on-elevated, fill-tertiary */
  --color-neutral-500:  #707679;  /* gray-500 — text-tertiary */
  --color-neutral-700:  #A1A9AD;  /* gray-300 — text-secondary */
  --color-neutral-900:  #F5F6F6;  /* gray-20 — text-strong, 로고(흰색) */
  --color-neutral-1000: #FFFFFF;

  /* Semantic (다크: 배경 8% 합성, 전경 한 단계 진하게) */
  --color-success-bg: #162517;  /* green-400 8% */
  --color-success-fg: #00A60E;  /* state-positive-primary (green-500) */
  --color-warning-bg: #2A1E1A;  /* orange-400 8% */
  --color-warning-fg: #E55C2E;  /* sub-orange-primary (orange-500) */
  --color-error-bg:   #2A1A1A;  /* red-400 8% */
  --color-error-fg:   #C42727;  /* state-negative-primary (red-600) */
  --color-info-bg:    #191F2A;  /* blue-400 8% */
  --color-info-fg:    #1D5FE3;  /* sub-blue-primary (blue-500) */

  /* Surface (배경 위계) */
  --bg-base:     #050505;             /* background-base (gray-990) */
  --bg-subtle:   #1F2020;             /* background-on-surface (gray-900) */
  --bg-elevated: #181818;             /* background-surface (gray-950) — 화면·카드 */
  --bg-overlay:  rgba(0, 0, 0, 0.50); /* background-dimmed */

  /* Text 위계 */
  --text-primary:    #E2E5E6;  /* text-primary (gray-50) */
  --text-secondary:  #A1A9AD;  /* text-secondary (gray-300) */
  --text-tertiary:   #707679;  /* text-tertiary (gray-500) */
  --text-on-primary: #FFFFFF;  /* static-white */
  --text-disabled:   #505456;  /* text-disabled (gray-600) */
  --text-strong:     #F5F6F6;  /* text-strong (gray-20) */

  /* Border */
  --border-default: #393B3D;  /* border-primary (gray-700) */
  --border-subtle:  rgba(255, 255, 255, 0.10);  /* divider-thin */
  --border-strong:  #AAB1B5;  /* border-active (gray-250) */
  --border-focus:   #F5F6F6;  /* (추정) */
}

[data-theme="light"] {
  /* Primary - Zigzag Pink (ZDS palette pink) */
  --color-primary-50:  #FEEEFA;  /* pink-50 — 선택 칩 배경 */
  --color-primary-100: #FDDEF6;  /* pink-100 */
  --color-primary-200: #FCCEF2;  /* pink-150 — brand-zigzag-border(라이트) */
  --color-primary-300: #FAAEEA;  /* pink-200 */
  --color-primary-400: #F88DE2;  /* pink-300 */
  --color-primary-500: #F55DD6;  /* pink-400 — brand-zigzag-primary: 찜·바로가기·스위치 ON */
  --color-primary-600: #E356C6;  /* pink-450 — button-pink-hovered */
  --color-primary-700: #D14FB7;  /* pink-550 — button-pink-pressed */
  --color-primary-800: #8F357C;  /* pink-700 */
  --color-primary-900: #4F1D45;  /* pink-900 */

  /* Secondary - 역할 색 (ZDS semantic) */
  --color-secondary-500: #6E52FF;  /* purple-400 — service-z-delivery(직진배송) 칩 */
  --color-accent-500:    #FB4333;  /* coral-red-400 — accent-primary: 상품 카드 할인율 */
  --color-ai-500:        #644BE8;  /* purple-500 — brand-ai-primary */
  --color-kakao:         #FEE500;  /* brand-kakao — 카카오 로그인 버튼 */

  /* Neutral - ZDS gray (살짝 푸른 회색) */
  --color-neutral-0:    #FFFFFF;  /* common-white — surface */
  --color-neutral-50:   #F9FAFA;  /* gray-10 — on-surface */
  --color-neutral-100:  #F5F6F6;  /* gray-20 — background-base, fill-tertiary */
  --color-neutral-200:  #ECEDEE;  /* gray-30 — border-primary, fill-secondary */
  --color-neutral-300:  #E2E5E6;  /* gray-50 — fill-primary */
  --color-neutral-500:  #878F91;  /* gray-400 — text-tertiary */
  --color-neutral-700:  #606567;  /* gray-550 — text-secondary */
  --color-neutral-900:  #121212;  /* gray-970 — text-strong, 로고(#121314) */
  --color-neutral-1000: #000000;

  /* Semantic (state-positive / negative + sub 팔레트, 배경은 12% 합성값) */
  --color-success-bg: #E0F7E2;  /* green-400 12% */
  --color-success-fg: #00BF10;  /* state-positive-primary */
  --color-warning-bg: #FFEDE7;  /* orange-400 12% (ZDS 에 warning 시맨틱 없음 — sub-orange 대용) */
  --color-warning-fg: #FF6734;  /* sub-orange-primary */
  --color-error-bg:   #FFE4E4;  /* red-400 12% */
  --color-error-fg:   #E52D2D;  /* state-negative-primary */
  --color-info-bg:    #E4EDFF;  /* blue-400 12% */
  --color-info-fg:    #216BFF;  /* sub-blue-primary (service-store-zigzin 도 같은 blue-400) */

  /* Surface (배경 위계) */
  --bg-base:     #F5F6F6;             /* background-base — 섹션 사이 회색 띠 */
  --bg-subtle:   #F9FAFA;             /* background-on-surface */
  --bg-elevated: #FFFFFF;             /* background-surface / elevated — 화면·카드·시트 */
  --bg-overlay:  rgba(0, 0, 0, 0.50); /* background-dimmed — 바텀시트 딤 */

  /* Text 위계 */
  --text-primary:    #292B2B;  /* text-primary (gray-800) — 본문·가격 */
  --text-secondary:  #606567;  /* text-secondary (gray-550) */
  --text-tertiary:   #878F91;  /* text-tertiary (gray-400) — 별점·캡션 */
  --text-on-primary: #FFFFFF;  /* static-white */
  --text-disabled:   #B3BABD;  /* text-disabled (gray-200) */
  --text-strong:     #121212;  /* text-strong (gray-970) — 헤더·탭 선택 */

  /* Border */
  --border-default: #ECEDEE;  /* border-primary (gray-30) */
  --border-subtle:  rgba(0, 0, 0, 0.05);  /* divider-thin */
  --border-strong:  #C6CBCD;  /* border-active (gray-100) */
  --border-focus:   #121212;  /* 입력 포커스 = 검정 테두리 (추정) */
}




.zz-btn { height: 48px; padding: 0 16px; border: 0; border-radius: var(--radius-md); font: 700 15px/22px Pretendard, sans-serif; letter-spacing: -0.1px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; cursor: pointer; transition: background var(--duration-fast) var(--ease-out); }
.zz-btn--primary { background: var(--text-strong); color: var(--text-on-primary); }          /* 구매하기·상품보기 = 검정 */
.zz-btn--primary:active { background: #292B2B; }
.zz-btn--pink { background: var(--color-primary-500); color: var(--text-on-primary); }       /* 바로가기·쿠폰받기 */
.zz-btn--pink:hover { background: var(--color-primary-600); }
.zz-btn--pink:active { background: var(--color-primary-700); }
.zz-btn--secondary { background: var(--bg-elevated); color: var(--text-strong); box-shadow: inset 0 0 0 1px var(--border-strong); }
.zz-btn--ghost { background: transparent; color: var(--text-secondary); }
.zz-btn--ghost:hover { background: var(--bg-base); }
.zz-btn--danger { background: var(--color-error-fg); color: var(--text-on-primary); }
.zz-btn:disabled { background: rgba(0,0,0,0.03); color: var(--text-disabled); box-shadow: none; cursor: not-allowed; }
.zz-btn.is-loading { color: transparent; position: relative; pointer-events: none; }
.zz-btn.is-loading::after { content: ""; position: absolute; width: 18px; height: 18px; border: 2px solid rgba(255,255,255,0.35); border-top-color: #fff; border-radius: 50%; animation: zz-spin 0.8s linear infinite; }
@keyframes zz-spin { to { transform: rotate(360deg); } }
.zz-btn--kakao { background: var(--color-kakao); color: var(--text-primary); border-radius: 24px; }  /* 카카오로 3초 만에 시작하기 */
.zz-input { height: 48px; padding: 0 14px; border: 0; border-radius: var(--radius-md); background: var(--bg-elevated); color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border-default); font: 400 15px/22px Pretendard, sans-serif; }
.zz-input:focus { outline: none; box-shadow: inset 0 0 0 1px var(--border-focus); }
.zz-input.is-error { box-shadow: inset 0 0 0 1px var(--color-error-fg); }   /* ZDS 실측: inset 1px state-negative */
.zz-input:disabled { box-shadow: inset 0 0 0 1px var(--border-default); background: var(--bg-base); color: var(--text-disabled); }
.zz-search { height: 40px; border-radius: var(--radius-md); background: var(--bg-base); padding: 0 12px; }
.zz-product { display: flex; flex-direction: column; gap: 2px; }
.zz-product__thumb { position: relative; aspect-ratio: 5 / 6; border-radius: var(--radius-sm); overflow: hidden; background: var(--bg-base); }
.zz-product__store { font: 600 12px/16px Pretendard, sans-serif; color: var(--text-primary); margin-top: 6px; }
.zz-product__name { font: 400 13px/18px Pretendard, sans-serif; color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.zz-product__price { font: 700 16px/22px Pretendard, sans-serif; color: var(--text-primary); }
.zz-product__price b { color: var(--color-accent-500); margin-right: 4px; }  /* 할인율 = accent-primary(coral-red) */
.zz-product--feature { background: var(--color-primary-50); border-radius: var(--radius-lg); padding: 12px; }   /* 강조형: 기획전 묶음 */
.zz-product--outlined .zz-product__thumb { box-shadow: inset 0 0 0 1px var(--border-default); }
.zz-badge { display: inline-flex; align-items: center; height: 18px; padding: 0 4px; border-radius: var(--radius-sm); font: 600 10px/14px Pretendard, sans-serif; }
.zz-badge--solid { background: var(--color-secondary-500); color: #fff; }             /* 직진배송 (사진 위) */
.zz-badge--subtle { background: var(--bg-base); color: var(--text-secondary); }       /* 무료배송 */
.zz-badge--pink { background: var(--color-primary-50); color: var(--color-primary-500); }  /* 첫구매가 */
.zz-badge--outline { box-shadow: inset 0 0 0 1px var(--border-strong); color: var(--text-secondary); }
.zz-chip { height: 32px; padding: 0 12px; border-radius: var(--radius-full); box-shadow: inset 0 0 0 1px var(--border-default); font: 500 13px/18px Pretendard, sans-serif; }
.zz-chip.is-selected { background: var(--text-strong); color: #fff; box-shadow: none; }  /* 필터 칩 선택 = 검정 채움 */
.zz-tabs { display: flex; gap: 16px; padding: 8px 16px; overflow-x: auto; font: 700 17px/24px Pretendard, sans-serif; }
.zz-tabs a { color: var(--text-disabled); position: relative; }
.zz-tabs a.is-active { color: var(--text-strong); }
.zz-tabs a.is-active::before { content: ""; position: absolute; left: 50%; top: -6px; width: 4px; height: 4px; margin-left: -2px; border-radius: 50%; background: currentColor; }  /* 선택 탭 위 점 */
.zz-tabs a.is-event { color: var(--color-secondary-500); }  /* 1만원특가 같은 이벤트 탭 */
.zz-tabbar { display: grid; grid-template-columns: repeat(5, 1fr); height: 56px; background: var(--bg-elevated); box-shadow: 0 -1px 0 var(--border-subtle); }
.zz-tabbar a { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; font: 500 10px/12px Pretendard, sans-serif; color: var(--text-disabled); }
.zz-tabbar a.is-active { color: var(--text-strong); }
